import test from 'node:test';
import assert from 'node:assert/strict';
import { hundredHandMile, configureHundredHandMilePorts } from '../src/systems/hundredHandMile.js';
import { HUNDRED_HAND_MILE as C, HUNDRED_HAND_POS as POS, HUNDRED_HAND_CHAPTERS,
  hundredHandEvidence, hundredHandContributionId, normalizeHundredHandMile, validHundredHandContribution } from '../src/data/hundredHandMile.js';
import { freshTowlineTable, towlineReceiptId, towlineCleanupId } from '../src/data/towlineTable.js';
import { TALLY_THREE } from '../src/data/tallyThree.js';

function fixture(enabled = true) {
  const state = { tick: 10, simTime: 10, settings: { gameplay: { hundredHandMileCandidate: enabled } },
    world: { currentSectorId: C.sectorId }, entities: new Map([[1, { id: 1, alive: true, pos: { ...POS } }]]), playerId: 1,
    salvage: { sources: { [TALLY_THREE.sourceKey]: { extracted: true, extractedBy: 'player', delivery: {
      receiptId: `tally-three:${TALLY_THREE.worldRecordId}`, sourceKey: TALLY_THREE.sourceKey,
      worldRecordId: TALLY_THREE.worldRecordId, stationId: TALLY_THREE.homeStationId,
      manifestId: TALLY_THREE.manifestId, commodityId: 'cmdty_salvage_electronics', qty: 4 } } } },
    towlineTable: freshTowlineTable() };
  const member = state.towlineTable.members.mara;
  member.source.status = 'cleared'; member.source.receipt = { id: towlineReceiptId('mara'), sourceId: towlineCleanupId('mara'),
    memberId: 'mara', stationId: 'station_ceres', by: 'player', at: 1 };
  const cargo = {}, physicalOwner = {}, receipts = new Map(), payments = new Set(), calls = [];
  const ports = { physicalOwner,
    inspectSite: () => ({ ok: true, siteId: C.siteId, tick: state.tick }),
    prepareContribution: (chapterId, { moduleId, generation, requirement }) => ({ ok: true, sourceId: generation || moduleId === 'cargo' ? 'player-hold' : `${C.siteId}:${moduleId}-original`, fingerprint: 'native-original-v1', qty: requirement.qty, commodityId: requirement.commodityId || (moduleId === 'power' ? 'cmdty_salvage_electronics' : 'cmdty_scrap_metal') }),
    verifyContributionReceipt: r => JSON.stringify(receipts.get(r.id)) === JSON.stringify(r),
    installationClear: () => ({ ok: true, tick: state.tick }),
    installModule: (id, r) => { calls.push(['install', id, r.id]); return { ok: true }; },
    settleMilestone: (chapter, id, cr) => { if (!payments.has(id)) { payments.add(id); calls.push(['pay', chapter, cr]); } },
    proveRoute: () => ({ ok: true, routeId: C.routeId, tick: state.tick }),
    dispatchConvoy: () => ({ ok: true, jobId: 'real-job' }),
    readConvoy: () => null };
  const owner = Object.create(hundredHandMile);
  owner.init({ state, registry: { get: name => name === 'cargo' ? cargo : null }, bus: { on: () => () => {}, emit: () => {} } });
  configureHundredHandMilePorts(state, ports);
  const accept = () => { assert.equal(owner.accept(owner._row.revision).ok, true); assert.equal(owner.survey().ok, true); };
  const deliver = (moduleId, generation = 0) => {
    const chapter = HUNDRED_HAND_CHAPTERS.find(c => c.moduleId === moduleId);
    const q = owner.prepareContribution(chapter.id); assert.equal(q.ok, true, q.reason);
    const r = { id: hundredHandContributionId(moduleId, generation), siteId: C.siteId, moduleId, generation,
      sourceId: q.sourceId, fingerprint: q.fingerprint, at: state.simTime, qty: q.requirement.qty,
      by: 'player', commodityId: q.commodityId };
    receipts.set(r.id, r); assert.equal(owner.acceptContribution(cargo, r).ok, true); return r;
  };
  const tick = () => { state.tick++; state.simTime += 3; owner.update(); };
  return { state, owner, ports, receipts, calls, cargo, physicalOwner, accept, deliver, tick };
}

test('explicit diagnostic opt-out disables admission and copied receipt ids cannot unlock offer', () => {
  const f = fixture(false); assert.equal(f.owner.accept(0).ok, false);
  f.state.settings.gameplay.hundredHandMileCandidate = true;
  f.state.salvage.sources = {}; f.state.towlineTable = freshTowlineTable();
  f.owner._row.prerequisiteReceiptIds = ['fake', 'fake2']; assert.equal(f.owner.evidence().eligible, false);
});
test('two families, not two Towline receipts, are required', () => {
  const f = fixture(); assert.equal(hundredHandEvidence(f.state).eligible, true);
  f.state.salvage.sources = {}; assert.equal(hundredHandEvidence(f.state).eligible, false);
});
test('five reviewed contract slices have fixed 600 credit ceiling', () => {
  assert.equal(HUNDRED_HAND_CHAPTERS.reduce((n, c) => n + c.rewardCr, 0), C.maxRewardCr);
  assert.equal(C.maxRewardCr, 600);
});
test('survey and contribution fail closed without native owner ports', () => {
  const f = fixture(); f.owner.accept(0); configureHundredHandMilePorts(f.state, null);
  assert.equal(f.owner.survey().ok, false); assert.equal(f.owner.prepareContribution('recover_power').ok, false);
});
test('untrusted actor and forged custody cannot install', () => {
  const f = fixture(); f.accept();
  const r = { id: hundredHandContributionId('power'), siteId: C.siteId, moduleId: 'power', generation: 0, sourceId: 'original', fingerprint: 'v1', at: 1, qty: 1, by: 'player', commodityId: null };
  assert.equal(f.owner.acceptContribution({}, r).reason, 'cargo-owner-required');
  assert.equal(f.owner.acceptContribution(f.cargo, r).reason, 'unverified-owner-custody');
});
test('occupancy postpones installation without consuming a second original', () => {
  const f = fixture(); f.accept(); const r = f.deliver('power');
  f.ports.installationClear = () => ({ ok: false, tick: f.state.tick }); f.tick();
  assert.deepEqual(f.owner._row.installedModuleIds, []); assert.equal(f.owner.acceptContribution(f.cargo, r).duplicate, true);
  f.ports.installationClear = () => ({ ok: true, tick: f.state.tick }); f.tick();
  assert.deepEqual(f.owner._row.installedModuleIds, ['power']); assert.equal(f.calls.filter(c => c[0] === 'install').length, 1);
});
test('alternate module order and dry cargo complete smaller working route', () => {
  const f = fixture(); f.accept(); f.deliver('cargo'); f.tick(); f.deliver('guide'); f.tick(); f.deliver('power'); f.tick();
  assert.equal(f.owner.dispatch().ok, true);
  f.ports.readConvoy = () => ({ jobId: 'real-job', routeId: C.routeId, outcome: 'arrived', witnessedByPlayer: true }); f.tick();
  assert.equal(f.owner._row.finalConvoyOutcome, 'arrived'); assert.equal(f.owner._row.branch, 'PARTIAL');
  assert.equal(f.owner._row.completedMilestoneIds.length, 5); assert.equal(f.owner.dispatch().ok, false);
});
test('destroy and repair spends a new receipt, never rewards twice or reinstalls destroyed replacement', () => {
  const f = fixture(); f.accept(); f.deliver('power'); f.tick(); f.owner.moduleDestroyed(f.physicalOwner, 'power'); f.tick();
  assert.deepEqual(f.owner._row.installedModuleIds, []);
  const repair = f.deliver('power', 1); assert.equal(repair.qty, 2); assert.equal(repair.commodityId, 'cmdty_scrap_metal'); f.tick();
  f.owner.moduleDestroyed(f.physicalOwner, 'power'); f.tick(); f.tick();
  assert.deepEqual(f.owner._row.installedModuleIds, []); assert.equal(f.calls.filter(c => c[0] === 'pay' && c[1] === 'recover_power').length, 1);
});
test('save/Continue rechecks custody and fresh native tick before completing install', () => {
  const f = fixture(); f.accept(); const r = f.deliver('power');
  f.owner.deserialize(f.owner.serialize()); f.tick(); assert.deepEqual(f.owner._row.installedModuleIds, []);
  f.tick(); assert.deepEqual(f.owner._row.installedModuleIds, ['power']);
  assert.equal(f.owner.acceptContribution(f.cargo, r).duplicate, true);
});
test('lost convoy cannot be respawned for a second payment', () => {
  const f = fixture(); f.accept(); f.deliver('power'); f.tick(); f.owner.dispatch();
  f.ports.readConvoy = () => ({ jobId: 'real-job', routeId: C.routeId, outcome: 'lost' }); f.tick();
  assert.equal(f.owner._row.finalConvoyOutcome, 'lost'); assert.equal(f.owner.dispatch().ok, false);
  assert.equal(f.owner._row.completedMilestoneIds.includes('witness_convoy'), false);
});
test('bounded normalized records reject fabricated malformed contributions', () => {
  const f = fixture(); f.accept(); f.deliver('power'); const saved = f.owner.serialize();
  saved.contributions.push(...Array(100).fill({ id: 'fake' })); saved.pendingInstall = { acceptedAt: -1000 };
  const r = normalizeHundredHandMile(saved); assert.equal(r.contributions.length, 1); assert.equal(r.pendingInstall, null);
  assert.equal(validHundredHandContribution({ ...r.contributions[0], generation: 1, qty: 1 }), false);
});

test('stale native clearance and route proof never authorize current actions', () => {
  const f = fixture(); f.accept();
  f.ports.installationClear = () => ({ ok: true, tick: f.state.tick - 1 });
  assert.equal(f.owner.prepareContribution('recover_power').ok, false);
  f.ports.installationClear = () => ({ ok: true, tick: f.state.tick }); f.deliver('power'); f.tick();
  f.ports.proveRoute = () => ({ ok: true, routeId: C.routeId, tick: f.state.tick - 1 });
  assert.equal(f.owner.dispatch().ok, false);
});
test('receipt replay after load does not repeat any of the bounded 600 credits', () => {
  const f = fixture(); f.accept(); for (const moduleId of ['power', 'guide', 'cargo']) { f.deliver(moduleId); f.tick(); }
  f.owner.dispatch(); f.ports.readConvoy = () => ({ jobId: 'real-job', routeId: C.routeId, outcome: 'arrived', witnessedByPlayer: true });
  f.tick(); f.tick(); const saved = f.owner.serialize(); f.owner.deserialize(saved); f.tick(); f.tick();
  assert.equal(f.calls.filter(c => c[0] === 'pay').reduce((n, c) => n + c[2], 0), 600);
  for (const r of f.receipts.values()) assert.equal(f.owner.acceptContribution(f.cargo, r).duplicate, true);
  f.tick(); assert.equal(f.calls.filter(c => c[0] === 'install').length, 3);
});
test('source removed on transfer boundary can recover through cargo without a fresh quote', () => {
  const f = fixture(); f.accept();
  f.ports.prepareContribution = () => ({ ok: false, reason: 'original-consumed' });
  let called = false; f.cargo.settleHundredHandContribution = () => { called = true; return { ok: true, recoveredCommittedCustody: true }; };
  assert.equal(f.owner.contribute('recover_power', f.owner._row.revision).ok, true); assert.equal(called, true);
});
test('leaving or abandoning keeps partial contributions and grants no convoy arrival', () => {
  const f = fixture(); f.accept(); f.deliver('power'); f.tick();
  f.owner.abandon(); f.tick(); assert.equal(f.owner._row.branch, 'ABANDONED');
  assert.deepEqual(f.owner._row.installedModuleIds, ['power']); assert.equal(f.owner.dispatch().ok, false);
  f.owner.accept(f.owner._row.revision); assert.equal(f.owner.dispatch().ok, true);
  f.state.entities.get(1).pos = { x: POS.x + 1000, z: POS.z };
  f.ports.readConvoy = () => ({ jobId: 'real-job', routeId: C.routeId, outcome: 'arrived', witnessedByPlayer: true }); f.tick();
  assert.equal(f.owner._row.completedMilestoneIds.includes('witness_convoy'), false);
});

