  row.settlement = { id: `${ILEX_ARK.id}:outcome`, stationId: ILEX_ARK.stationId, deliveredVaultIds: [],
    at: 1, harvestAt: 1 + ILEX_ARK.harvestDelayS, rewardCr: 0 };
  f.state.ilexArk = row;
