  row.settlement.rewardCr = ILEX_ARK.baseRewardCr + ILEX_ARK.vaultRewardCr;
  assert.equal(f.owner.evidence().cargoVariant, 'seed'); assert.deepEqual(f.owner.readout().cargoRequirement, { commodityId: 'cmdty_food', qty: 4 });
  // A claimed surviving line without corresponding vault custody is not a surviving seed.
