import test from 'node:test';
import assert from 'node:assert/strict';
import { createSimulation } from '../src/core/sim.js';
import { npcJobsRuntime } from '../src/systems/npcJobsRuntime.js';
import { spawnBudget } from '../src/systems/spawnBudget.js';
import { hundredHandMileTraffic, MILE_CONVOY_JOB, MILE_CONVOY_ROUTE, MILE_CONVOY_RECORD } from '../src/systems/hundredHandMileTraffic.js';
import { HUNDRED_HAND_MILE as C, HUNDRED_HAND_POS as POS } from '../src/data/hundredHandMile.js';

function boot(enabled = true) {
  const native = new Map(); let clear = true;
  const world = { name: 'hundredHandMileWorld', init(ctx) { this.state = ctx.state; },
    proveRoute() { return { ok: clear, routeId: C.routeId, tick: this.state.tick, nativeTick: this.state.tick }; },
    nativePosition(entity) { return native.get(entity) || null; } };
  const sim = createSimulation({ seed: 44, systems: [spawnBudget, npcJobsRuntime, world, hundredHandMileTraffic] });
  sim.state.mode = 'flight'; sim.state.world.currentSectorId = C.sectorId;
  sim.state.settings.gameplay.hundredHandMileCandidate = enabled;
  const player = sim.spawn({ type: 'ship', team: 0, hull: 100, pos: { ...POS } });
  sim.state.playerId = player.id; native.set(player, { ...POS });
  const owner = sim.registry.get('hundredHandMileTraffic');
  const dispatch = () => owner.dispatchConvoy(owner.proveRoute());
  const row = () => sim.helpers.npcJobs.get(MILE_CONVOY_JOB);
  const hull = () => sim.state.entities.get(row()?.entityId);
  return { sim, native, player, owner, dispatch, row, hull, block: () => { clear = false; } };
}
const steps = (f, n) => { for (let i = 0; i < n; i++) f.sim.step(1 / 60); };

test('candidate defaults off, authentic current clearance and mandatory budget admit one real job', () => {
  let f = boot(false); assert.equal(f.dispatch().ok, false); assert.equal(f.row(), null);
  f = boot(); const proof = f.owner.proveRoute();
  assert.equal(f.owner.dispatchConvoy({ ...proof }).ok, false);
  f.block(); assert.equal(f.owner.dispatchConvoy(proof).ok, false);
  f = boot(); f.sim.helpers.spawnBudget.request(999, 'other'); assert.equal(f.dispatch().ok, false);
  f = boot(); assert.equal(f.dispatch().jobId, MILE_CONVOY_JOB);
  const hull = f.hull(); assert.equal(hull.type, 'ship'); assert.equal(hull.data.worldRecordId, MILE_CONVOY_RECORD);
  assert.equal(f.dispatch().duplicate, true); assert.equal(f.hull(), hull);
});

test('runtime cannot finish by timer/render pose; native traversal and live witness finish once', () => {
  const f = boot(); assert.equal(f.dispatch().ok, true); const hull = f.hull();
  hull.pos = { ...MILE_CONVOY_ROUTE[1] }; steps(f, 1200);
  assert.equal(f.owner.readConvoy(MILE_CONVOY_JOB).outcome, null);
  f.native.set(hull, { ...MILE_CONVOY_ROUTE[0] }); steps(f, 150);
  f.native.set(hull, { x: POS.x, z: POS.z - 100 }); steps(f, 1);
  f.native.set(hull, { ...MILE_CONVOY_ROUTE[1] }); steps(f, 1500);
  assert.equal(f.owner.readConvoy(MILE_CONVOY_JOB).outcome, 'arrived');
  assert.equal(f.owner.readConvoy(MILE_CONVOY_JOB).witnessedByPlayer, true);
  assert.equal(f.row(), null, 'ordinary runtime retires terminal job');
  const saved = f.owner.serialize(); f.owner.deserialize(saved);
  assert.equal(f.owner.readConvoy(MILE_CONVOY_JOB).outcome, 'arrived'); assert.equal(f.dispatch().duplicate, true);
});

test('arrival without the player native body is not a witness', () => {
  const f = boot(); f.dispatch(); const hull = f.hull();
  f.native.set(hull, { ...MILE_CONVOY_ROUTE[0] }); steps(f, 1);
  f.native.set(hull, { x: POS.x, z: POS.z - 100 }); steps(f, 1);
  f.native.set(hull, { ...MILE_CONVOY_ROUTE[1] }); f.native.delete(f.player); steps(f, 1500);
  assert.equal(f.owner.readConvoy(MILE_CONVOY_JOB).outcome, 'arrived');
  assert.equal(f.owner.readConvoy(MILE_CONVOY_JOB).witnessedByPlayer, false);
});

test('ordinary job aims through the actual midpoint until native crossing is observed', () => {
  const f=boot();f.dispatch();const hull=f.hull(),entry=f.row();
  f.native.set(hull,{...MILE_CONVOY_ROUTE[0]});f.owner.canAdvanceJob(entry,hull);
  for(const phase of ['transit','approach']){
    entry.job.phase=phase;
    assert.deepEqual(f.owner.jobTarget(entry,hull).pos,{x:POS.x,z:POS.z-100});
  }
  assert.equal(f.owner.canAdvanceJob(entry,hull),false,'an expired transit timer cannot stand in for crossing');
  f.native.set(hull,{x:POS.x,z:POS.z-100});f.owner.canAdvanceJob(entry,hull);
  assert.deepEqual(f.owner.jobTarget(entry,hull).pos,MILE_CONVOY_ROUTE[1]);
});

test('native Mile job cancels lateral velocity with ordinary thrust, without writing pose', () => {
  const f=boot();f.dispatch();const hull=f.hull(),entry=f.row(),runtime=f.sim.registry.get('npcJobsRuntime');
  f.native.set(hull,{...MILE_CONVOY_ROUTE[0]});entry.job.phase='transit';
  hull.rot=0;hull.vel.x=0;hull.vel.z=20;
  const before={pos:{...hull.pos},vel:{...hull.vel},rot:hull.rot},calls=[];
  runtime._writeIntent=(entity,moveX,moveZ,boost,aimAngle,brake)=>calls.push({entity,moveX,moveZ,boost,aimAngle,brake});
  runtime._drive(entry,hull);assert.equal(calls.length,1);
  assert.equal(calls[0].entity,hull);assert(calls[0].moveX<0,'native lateral drift receives opposing RCS');
  assert(calls[0].moveZ>0,'forward route travel remains an ordinary thrust command');
  assert(Math.abs(calls[0].moveX)<=1&&Math.abs(calls[0].moveZ)<=1);
  assert.equal(calls[0].boost,false);assert.equal(calls[0].brake,false);
  assert.deepEqual({pos:{...hull.pos},vel:{...hull.vel},rot:hull.rot},before);
});

test('Continue retains the real job without virtual catch-up or duplicate spawn', () => {
  const f = boot(); f.dispatch(); const hull = f.hull();
  f.native.set(hull, { ...MILE_CONVOY_ROUTE[0] }); steps(f, 1);
  const rt = f.sim.registry.get('npcJobsRuntime'), savedJobs = rt.serialize(), saved = f.owner.serialize();
  f.sim.bus.emit('save:restoring'); rt.deserialize(savedJobs); f.owner.deserialize(saved);
  f.sim.state.simTime += 10000; f.sim.bus.emit('save:loaded');
  assert.equal(f.row().job.phase, savedJobs.byId[MILE_CONVOY_JOB].job.phase);
  assert.equal(f.owner.readConvoy(MILE_CONVOY_JOB).outcome, null);
  assert.equal(f.dispatch().duplicate, true);
});

test('loss is conserved; stale numeric-id destruction cannot kill the real convoy', () => {
  const f = boot(); f.dispatch(); const hull = f.hull();
  f.sim.bus.emit('entity:destroyed', { id: hull.id, entity: { ...hull } });
  assert.equal(f.owner.readConvoy(MILE_CONVOY_JOB).outcome, null);
  assert.ok(f.row(), 'stale destruction must not release the runtime job either');
  f.sim.bus.emit('entity:destroyed', { id: hull.id, entity: hull });
  assert.equal(f.owner.readConvoy(MILE_CONVOY_JOB).outcome, 'lost');
  const save = f.owner.serialize(); f.owner.deserialize(save); assert.equal(f.dispatch().duplicate, true);
});

test('duplicate durable hull and recycled live entity fail physical authority', () => {
  const f = boot(); f.dispatch(); const hull = f.hull(), entry = f.row();
