  h.graph.verifyContributionQuote = () => true; h.state.fixtureSealed = ['cmdty_food'];
  assert.equal(h.c.settleHundredHandContribution({ chapterId: 'deliver_cargo' }).ok, false);
  h.state.fixtureSealed = []; h.state.settings.gameplay.hundredHandMileCandidate = false;
  assert.equal(h.c.settleHundredHandContribution({ chapterId: 'deliver_cargo' }).ok, false);
  assert.equal(h.state.player.cargo.items.cmdty_food, 8);
});

test('source originals exhaust exact finite salvage, serialize receipt, and never debit hold', () => {
  for (const moduleId of ['power', 'guide']) {
    const h = fixture(moduleId), d = h.s.hundredHandSourceDescriptor(moduleId), hold = structuredClone(h.state.player.cargo);
    assert.equal(h.c.settleHundredHandContribution({ chapterId: h.quote.chapterId }).ok, true);
