test('five authored milestones cap at 600 credits, duplicate/repaired milestones never repay', () => {
  const h = fixture();
  for (const chapter of HUNDRED_HAND_CHAPTERS) {
    const receipt = { id: hundredHandMilestoneId(chapter.id), siteId: C.siteId, chapterId: chapter.id, rewardCr: chapter.rewardCr };
    assert.equal(h.e.settleHundredHandMilestone(receipt).ok, true);
