test('economy refuses absent graph proof; retries prewrite faults and retains postwrite faults', () => {
  const h = fixture(), receipt = { id: hundredHandMilestoneId('survey'), siteId: C.siteId, chapterId: 'survey', rewardCr: 80 };
  h.graph.verifyMilestoneReceipt = () => false; assert.equal(h.e.settleHundredHandMilestone(receipt).ok, false);
  h.graph.verifyMilestoneReceipt = () => true;
  const grant = h.e.grantCredits; h.e.grantCredits = () => false;
